def diagonal_sequence(grid, bbox, bg, corner):
    r0,r1,c0,c1=bbox
    corners = {
      'br': (r1,c1,-1,-1), 'bl': (r1,c0,-1,1),
      'tr': (r0,c1,1,-1), 'tl': (r0,c0,1,1)
    }
    ar,ac,sr,sc=corners[corner]
    seq=[]; saw_marker=False
    for d in range(min(r1-r0,c1-c0)+1):
      v=grid[ar+sr*d][ac+sc*d]
      if d==0:
        seq.append(v)
        if v!=bg: saw_marker=True
      elif v==bg:
        if saw_marker: break
        # Corner background is the base layer; no seed encountered by this point.
        break
      else:
        seq.append(v);saw_marker=True
    return seq if saw_marker else []

def solve_ring(grid, wall, bg):
  h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]; infos=[]
  corner_order=['br','bl','tr','tl']
  for r in range(h):
    for c in range(w):
      if grid[r][c]==wall or (r,c) in seen: continue
      q=[(r,c)];seen.add((r,c)); cells=[]
      for rr,cc in q:
        cells.append((rr,cc))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
          nr,nc=rr+dr,cc+dc
          if 0<=nr<h and 0<=nc<w and grid[nr][nc]!=wall and (nr,nc) not in seen:
            seen.add((nr,nc));q.append((nr,nc))
      r0=min(x[0] for x in cells); r1=max(x[0] for x in cells)
      c0=min(x[1] for x in cells); c1=max(x[1] for x in cells)
      bbox=(r0,r1,c0,c1)
      seq=[];anchor=None
      for corner in corner_order:
        maybe=diagonal_sequence(grid,bbox,bg,corner)
        if maybe:
          seq=maybe; anchor=corner;break
      if seq:
        for rr,cc in cells:
          d=min(rr-r0,r1-rr,cc-c0,c1-cc)
          out[rr][cc]=seq[d%len(seq)]
      infos.append((bbox,len(cells),anchor,seq,[(rr,cc,grid[rr][cc]) for rr,cc in cells if grid[rr][cc] != bg]))
  return out,infos
